// Classer un test selon son historique d'exécutions.
export function classifyTest(history) {
  if (history.every((r) => r === 'pass')) return 'healthy';
  if (history.every((r) => r === 'fail')) return 'broken';
  // BUG : tout mélange est traité comme instable, sans repérer une régression nette.
  return 'flaky';
}

